"use client";

import React from "react";
import { motion } from "framer-motion";
import { BRAND, FONT, fadeUp } from "@/lib/brand";
import { SectionEyebrow } from "@/components/shared/section-eyebrow";
import { DashboardMockup } from "@/components/dashboard/dashboard-mockup";

export function Shift() {
  return (
    <section
      style={{
        position: "relative",
        background: BRAND.bone,
        paddingTop: 100,
        paddingBottom: 100,
        overflow: "hidden",
      } as React.CSSProperties}
    >
      {/* Subtle radial amberWash at bottom */}
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          bottom: 0,
          left: "50%",
          transform: "translateX(-50%)",
          width: 900,
          height: 500,
          background: `radial-gradient(ellipse 80% 60% at 50% 100%, ${BRAND.amberWash} 0%, transparent 70%)`,
          pointerEvents: "none",
        } as React.CSSProperties}
      />

      <div
        style={{
          position: "relative",
          maxWidth: 1120,
          margin: "0 auto",
          padding: "0 24px",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          textAlign: "center",
        } as React.CSSProperties}
      >
        {/* Eyebrow */}
        <motion.div
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-80px" }}
        >
          <SectionEyebrow label="The shift" accent="amber" />
        </motion.div>

        {/* Heading */}
        <motion.h2
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-80px" }}
          style={{
            fontFamily: FONT.sans,
            fontSize: "clamp(32px, 4.2vw, 54px)",
            lineHeight: 1.08,
            letterSpacing: "-0.025em",
            color: BRAND.onyx,
            fontWeight: 600,
            marginBottom: 18,
            maxWidth: 720,
          } as React.CSSProperties}
        >
          One quiet system, holding every loop.
        </motion.h2>

        {/* Subhead */}
        <motion.p
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-80px" }}
          style={{
            fontFamily: FONT.sans,
            fontSize: 17,
            lineHeight: 1.65,
            color: BRAND.stoneDark,
            maxWidth: 580,
            marginBottom: 60,
          } as React.CSSProperties}
        >
          Sessions linked into projects. Deposits pooled per sleeve. Allergies surfaced before the chair. Residencies tracked without a spreadsheet. InkOS runs in the background so you don&apos;t have to.
        </motion.p>

        {/* Dashboard */}
        <motion.div
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-60px" }}
          style={{ width: "100%" } as React.CSSProperties}
        >
          <DashboardMockup hero={false} />
        </motion.div>
      </div>
    </section>
  );
}

"use client";

import React from "react";
import {
  Sparkles, Inbox, Calendar, MessageSquare, Clock,
  Users, LayoutGrid, ImageIcon, FileText, CreditCard,
  Package, BarChart3, Settings, ChevronRight,
  AlertTriangle, TrendingUp, Zap,
} from "lucide-react";
import { BRAND, FONT } from "@/lib/brand";

// ─── Types ────────────────────────────────────────────────────────────────────

interface NavGroupProps {
  title: string;
  items: Array<{
    icon: React.ComponentType<{ size?: number; strokeWidth?: number }>;
    label: string;
    active?: boolean;
    badge?: number;
    tag?: string;
  }>;
}

interface ScheduleRowProps {
  row: {
    t: string;
    d: string;
    c: string;
    p: string;
    a: string;
    status?: "live" | "next";
    warn?: boolean;
  };
  first: boolean;
}

interface ProjectRowProps {
  row: {
    c: string;
    s: string;
    dep: string;
    dot: string;
    pct: number;
  };
  first: boolean;
}

interface DashboardMockupProps {
  hero?: boolean;
}

// ─── NavGroup ─────────────────────────────────────────────────────────────────

function NavGroup({ title, items }: NavGroupProps) {
  return (
    <div style={{ marginBottom: 20 } as React.CSSProperties}>
      <div style={{
        fontFamily: FONT.sans,
        fontSize: 10,
        fontWeight: 600,
        color: "#5A5755",
        letterSpacing: "0.08em",
        textTransform: "uppercase",
        padding: "0 12px",
        marginBottom: 4,
      } as React.CSSProperties}>{title}</div>
      {items.map((item) => {
        const Icon = item.icon;
        return (
          <div
            key={item.label}
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              padding: "6px 12px",
              borderRadius: 7,
              background: item.active ? "rgba(200,53,31,0.15)" : "transparent",
              marginBottom: 1,
              cursor: "pointer",
            } as React.CSSProperties}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 8 } as React.CSSProperties}>
              <Icon size={13} strokeWidth={1.8} />
              <span style={{
                fontFamily: FONT.sans,
                fontSize: 12,
                fontWeight: item.active ? 500 : 400,
                color: item.active ? BRAND.rustBright : "#9A9792",
                letterSpacing: "-0.01em",
              } as React.CSSProperties}>{item.label}</span>
            </div>
            {item.badge !== undefined && item.badge > 0 && (
              <span style={{
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
                minWidth: 16,
                height: 16,
                borderRadius: 100,
                background: BRAND.rust,
                fontFamily: FONT.sans,
                fontSize: 9,
                fontWeight: 600,
                color: BRAND.white,
                padding: "0 4px",
              } as React.CSSProperties}>{item.badge}</span>
            )}
            {item.tag && (
              <span style={{
                fontFamily: FONT.sans,
                fontSize: 9,
                color: BRAND.amber,
                background: "rgba(216,149,56,0.15)",
                padding: "1px 5px",
                borderRadius: 4,
                fontWeight: 500,
              } as React.CSSProperties}>{item.tag}</span>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ─── DashSectionHeader ────────────────────────────────────────────────────────

function DashSectionHeader({ label, action }: { label: string; action?: string }) {
  return (
    <div style={{
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      marginBottom: 10,
    } as React.CSSProperties}>
      <span style={{
        fontFamily: FONT.sans,
        fontSize: 11,
        fontWeight: 600,
        color: BRAND.stoneDark,
        letterSpacing: "0.04em",
        textTransform: "uppercase",
      } as React.CSSProperties}>{label}</span>
      {action && (
        <button style={{
          display: "flex",
          alignItems: "center",
          gap: 2,
          background: "none",
          border: "none",
          cursor: "pointer",
          fontFamily: FONT.sans,
          fontSize: 10,
          color: BRAND.stone,
          padding: 0,
        } as React.CSSProperties}>
          {action}
          <ChevronRight size={10} strokeWidth={2} />
        </button>
      )}
    </div>
  );
}

// ─── ScheduleRow ──────────────────────────────────────────────────────────────

function ScheduleRow({ row }: ScheduleRowProps) {
  return (
    <div style={{
      display: "grid",
      gridTemplateColumns: "52px 40px 1fr 90px 64px 48px",
      alignItems: "center",
      gap: 8,
      padding: "7px 10px",
      borderRadius: 7,
      background: row.status === "live"
        ? "rgba(200,53,31,0.06)"
        : row.status === "next"
        ? "rgba(247,247,245,0.8)"
        : "transparent",
      border: row.status === "live"
        ? `1px solid rgba(200,53,31,0.15)`
        : "1px solid transparent",
      marginBottom: 3,
    } as React.CSSProperties}>
      <span style={{
        fontFamily: FONT.mono,
        fontSize: 10,
        color: row.status === "live" ? BRAND.rust : BRAND.stone,
        fontWeight: row.status === "live" ? 600 : 400,
      } as React.CSSProperties}>{row.t}</span>

      <span style={{
        fontFamily: FONT.sans,
        fontSize: 9,
        color: BRAND.stoneLight,
        background: BRAND.boneDeep,
        padding: "2px 5px",
        borderRadius: 4,
        textAlign: "center",
      } as React.CSSProperties}>{row.d}</span>

      <div style={{ display: "flex", alignItems: "center", gap: 6 } as React.CSSProperties}>
        {row.warn && (
          <AlertTriangle
            size={10}
            strokeWidth={2}
            style={{ color: BRAND.amber, flexShrink: 0 } as React.CSSProperties}
          />
        )}
        <span style={{
          fontFamily: FONT.sans,
          fontSize: 11,
          color: BRAND.ink,
          fontWeight: 500,
          whiteSpace: "nowrap",
          overflow: "hidden",
          textOverflow: "ellipsis",
        } as React.CSSProperties}>{row.c}</span>
      </div>

      <span style={{
        fontFamily: FONT.sans,
        fontSize: 10,
        color: BRAND.stone,
        whiteSpace: "nowrap",
        overflow: "hidden",
        textOverflow: "ellipsis",
      } as React.CSSProperties}>{row.p}</span>

      <span style={{
        fontFamily: FONT.sans,
        fontSize: 10,
        color: BRAND.stoneDark,
        whiteSpace: "nowrap",
        overflow: "hidden",
        textOverflow: "ellipsis",
      } as React.CSSProperties}>{row.a}</span>

      <div style={{ display: "flex", justifyContent: "flex-end" } as React.CSSProperties}>
        {row.status === "live" && (
          <span style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 3,
            background: BRAND.rust,
            color: BRAND.white,
            fontFamily: FONT.sans,
            fontSize: 8,
            fontWeight: 600,
            padding: "2px 6px",
            borderRadius: 4,
            letterSpacing: "0.04em",
            textTransform: "uppercase",
          } as React.CSSProperties}>
            <span style={{
              width: 4,
              height: 4,
              borderRadius: 100,
              background: BRAND.white,
              display: "inline-block",
              animation: "inkos-pulse 1.4s ease-in-out infinite",
            } as React.CSSProperties} />
            LIVE
          </span>
        )}
        {row.status === "next" && (
          <span style={{
            fontFamily: FONT.sans,
            fontSize: 8,
            color: BRAND.stoneDark,
            background: BRAND.boneDeep,
            padding: "2px 6px",
            borderRadius: 4,
            letterSpacing: "0.02em",
          } as React.CSSProperties}>NEXT</span>
        )}
      </div>
    </div>
  );
}

// ─── ProjectRow ───────────────────────────────────────────────────────────────

function ProjectRow({ row }: ProjectRowProps) {
  return (
    <div style={{
      display: "grid",
      gridTemplateColumns: "1fr 80px 80px 64px",
      alignItems: "center",
      gap: 8,
      padding: "7px 10px",
      borderRadius: 7,
      marginBottom: 3,
    } as React.CSSProperties}>
      <div style={{ display: "flex", alignItems: "center", gap: 6 } as React.CSSProperties}>
        <span style={{
          width: 7,
          height: 7,
          borderRadius: 100,
          background: row.dot,
          display: "inline-block",
          flexShrink: 0,
        } as React.CSSProperties} />
        <span style={{
          fontFamily: FONT.sans,
          fontSize: 11,
          fontWeight: 500,
          color: BRAND.ink,
        } as React.CSSProperties}>{row.c}</span>
      </div>

      <span style={{
        fontFamily: FONT.sans,
        fontSize: 10,
        color: BRAND.stone,
      } as React.CSSProperties}>{row.s}</span>

      <span style={{
        fontFamily: FONT.sans,
        fontSize: 10,
        color: BRAND.stoneDark,
        fontWeight: 500,
      } as React.CSSProperties}>{row.dep}</span>

      <div>
        <div style={{
          height: 4,
          borderRadius: 100,
          background: BRAND.boneDeep,
          overflow: "hidden",
        } as React.CSSProperties}>
          <div style={{
            height: "100%",
            width: `${row.pct}%`,
            borderRadius: 100,
            background: row.pct >= 80 ? BRAND.sage : row.pct >= 50 ? BRAND.amber : BRAND.rust,
            transition: "width 0.3s ease",
          } as React.CSSProperties} />
        </div>
        <div style={{
          fontFamily: FONT.mono,
          fontSize: 9,
          color: BRAND.stoneLight,
          marginTop: 2,
          textAlign: "right",
        } as React.CSSProperties}>{row.pct}%</div>
      </div>
    </div>
  );
}

// ─── Data ─────────────────────────────────────────────────────────────────────

const scheduleRows: ScheduleRowProps["row"][] = [
  { t: "10:00", d: "3h",   c: "Asha Mehra",  p: "Sleeve — session 4",   a: "Zara K.", status: "live" },
