                fontWeight: 500,
                color: BRAND.bone,
                whiteSpace: "nowrap",
                overflow: "hidden",
                textOverflow: "ellipsis",
              } as React.CSSProperties}>Zara Kowalski</div>
              <div style={{
                fontFamily: FONT.sans,
                fontSize: 9,
                color: "#5A5755",
              } as React.CSSProperties}>Lead artist</div>
            </div>
            <Settings
              size={12}
              strokeWidth={1.8}
              style={{ color: "#5A5755", flexShrink: 0 } as React.CSSProperties}
            />
          </div>
        </div>

        {/* Main area */}
        <div style={{
          background: BRAND.bone,
          overflowY: "auto",
          padding: "18px 20px",
          display: "flex",
          flexDirection: "column",
          gap: 18,
        } as React.CSSProperties}>

          {/* Page header */}
          <div style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          } as React.CSSProperties}>
            <div>
              <div style={{
                fontFamily: FONT.serif,
                fontSize: 20,
                color: BRAND.ink,
                lineHeight: 1.2,
              } as React.CSSProperties}>Good morning, Zara</div>
              <div style={{
                fontFamily: FONT.sans,
                fontSize: 12,
                color: BRAND.stone,
                marginTop: 2,
              } as React.CSSProperties}>Monday, 27 April — 4 appointments today</div>
