              fontFamily: FONT.sans,
              fontSize: 11,
              fontWeight: 500,
              color: BRAND.bone,
            } as React.CSSProperties}>
              <Clock size={11} strokeWidth={2} />
              New booking
            </button>
          </div>

          {/* KPI grid */}
          <div style={{
            display: "grid",
            gridTemplateColumns: "repeat(4, 1fr)",
            gap: 10,
          } as React.CSSProperties}>
            {kpis.map((kpi) => {
