            bottom: 10,
            right: 12,
            fontFamily: FONT.mono,
            fontSize: 9,
            fontWeight: 600,
            color: stage.strip,
            letterSpacing: "0.06em",
          } as React.CSSProperties}
        >
          {stage.day.replace("Day ", "D ")}
        </div>
      </div>

      {/* Label below panel */}
      <div style={{ paddingTop: 14, paddingLeft: 4 } as React.CSSProperties}>
        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            gap: 8,
            marginBottom: 4,
