          >
            {stage.label}
          </span>
          <span
            style={{
              fontFamily: FONT.mono,
              fontSize: 10.5,
              color: stage.strip,
              fontWeight: 600,
            } as React.CSSProperties}
          >
            &middot; {stage.day}
          </span>
        </div>
        <div
          style={{
            fontFamily: FONT.sans,
            fontSize: 12.5,
            fontWeight: 400,
            color: BRAND.stoneDark,
            lineHeight: 1.45,
          } as React.CSSProperties}
        >
          {stage.desc}
        </div>
      </div>
    </div>
  );
}

// ── PolaroidTimelineBright ────────────────────────────────────────────────────

function PolaroidTimelineBright() {
  return (
