                width: 6,
                height: 6,
                borderRadius: 100,
                background: BRAND.sage,
                display: "inline-block",
                animation: "inkos-pulse 2s ease-in-out infinite",
              } as React.CSSProperties} />
              <span style={{
                fontFamily: FONT.mono,
                fontSize: 12,
                color: BRAND.stoneDark,
                letterSpacing: "0.04em",
