import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ArrowRight, ArrowUpRight, Menu, X,
  Sparkles, Inbox, Calendar, MessageSquare, Clock, LayoutGrid,
  Users, Heart, Briefcase, ChevronDown, Plus, Bell,
  AlertCircle, TrendingUp, CheckCircle2,
  Image as ImageIcon, FileText, CreditCard, Package, BarChart3, Megaphone,
  Star, Shield, MapPin, Globe, Database,
} from 'lucide-react';

/* =========================================================================
   INKOS â TODAY PAGE (STANDALONE)
   The morning launchpad. Page 1 of 15.
   Editorial luxury Â· Bone / Onyx / Stone / Rust Â· Instrument Serif + Inter
   ========================================================================= */

const BRAND = {
  bone: '#F7F7F5',
  boneDeep: '#EFEEEA',
  boneCream: '#FAFAF8',
  onyx: '#0F0F0F',
  onyxSoft: '#1A1A1A',
  stone: '#787774',
  stoneLight: '#9A9792',
  stoneDark: '#4B4842',
  border: '#E7E5E1',
  borderSoft: '#EFEEEA',
  rust: '#B23A2B',
  rustBright: '#D9574A',
  rustSoft: '#FBECEA',
  rustDeep: '#7A2619',
  success: '#22A06B',
  warn: '#D97706',
  danger: '#DC2626',
  dangerSoft: '#FEF2F2',
  dangerBorder: '#FCA5A5',
};

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.7, ease: [0.22, 1, 0.36, 1] } },
};
const stagger = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.08, delayChildren: 0.1 } },
};

/* =========================================================================
   NAV â full mega-menu navigation with dropdowns
   ========================================================================= */
function MiniNav() {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  const [activeMenu, setActiveMenu] = useState(null);
  const [mobileExpanded, setMobileExpanded] = useState(null);
  const closeTimer = useRef(null);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  // Hover bridge â small delay so cursor can travel from trigger â panel
  const handleEnter = (label) => {
    if (closeTimer.current) clearTimeout(closeTimer.current);
    setActiveMenu(label);
  };
  const handleLeave = () => {
    closeTimer.current = setTimeout(() => setActiveMenu(null), 120);
  };

  const navItems = [
    {
      label: 'Product',
      type: 'mega',
      columns: [
        {
          title: 'Run the day',
          items: [
            { icon: Sparkles, name: 'Today', desc: 'Morning launchpad', href: '#' },
            { icon: Inbox, name: 'Inbox', desc: 'Action items in one feed', href: '#' },
            { icon: Calendar, name: 'Calendar', desc: 'Multi-chair scheduling', href: '#' },
            { icon: MessageSquare, name: 'Messages', desc: 'Unified client chat', href: '#' },
            { icon: Clock, name: 'Appointments', desc: 'Booking & deposits', href: '#' },
          ],
        },
        {
          title: 'Clients & creative',
          items: [
            { icon: Users, name: 'Clients', desc: 'CRM with allergy alerts', href: '#' },
            { icon: LayoutGrid, name: 'Projects', desc: 'Multi-session sleeves', href: '#' },
            { icon: ImageIcon, name: 'Flash & Portfolio', desc: 'Design library', href: '#' },
            { icon: FileText, name: 'Forms', desc: 'Consent & waivers', href: '#' },
          ],
        },
        {
          title: 'Studio operations',
          items: [
            { icon: Users, name: 'Team', desc: 'Artists, guests, payroll', href: '#' },
            { icon: CreditCard, name: 'Payments', desc: 'Commission auto-splits', href: '#' },
            { icon: Package, name: 'Inventory', desc: 'Ink, needles, REACH', href: '#' },
          ],
        },
        {
          title: 'Grow',
          items: [
            { icon: BarChart3, name: 'Analytics', desc: 'Revenue, retention, mix', href: '#' },
            { icon: Megaphone, name: 'Marketing', desc: 'Campaigns & loyalty', href: '#' },
            { icon: Sparkles, name: 'AI Studio', desc: 'Design assist & briefs', href: '#' },
          ],
        },
      ],
      footer: {
        title: 'The studio OS for tattoo',
        desc: 'Fifteen modules, one source of truth â built for resident, guest, and chain studios.',
        ctaLabel: 'See full product tour',
        ctaHref: '#',
      },
    },
    {
      label: 'Solutions',
      type: 'mega',
      columns: [
        {
          title: 'By studio size',
          items: [
            { icon: Star, name: 'Solo artists', desc: 'One chair, full kit Â· $29/mo', href: '#' },
            { icon: Users, name: 'Small studios', desc: '2â5 chairs Â· $59/mo', href: '#' },
            { icon: LayoutGrid, name: 'Multi-chair shops', desc: '6+ chairs, multiple artists Â· $99/mo', href: '#' },
            { icon: Globe, name: 'Multi-location chains', desc: 'Enterprise scale Â· $199/mo', href: '#' },
          ],
        },
        {
          title: 'By goal',
          items: [
            { icon: ArrowUpRight, name: 'Migrate from DaySmart', desc: '14-day white-glove move', href: '#' },
            { icon: ArrowUpRight, name: 'Migrate from Fresha', desc: 'Keep your client list', href: '#' },
            { icon: Shield, name: 'EU REACH compliance', desc: 'Ink registry built-in', href: '#' },
            { icon: MapPin, name: 'Guest artist tours', desc: 'Time-boxed residencies', href: '#' },
          ],
        },
      ],
      footer: {
        title: 'Migrate in 14 days',
        desc: 'White-glove import from any tattoo or salon SaaS. Zero data loss, zero downtime.',
        ctaLabel: 'Talk to migrations team',
        ctaHref: '#',
      },
    },
    { label: 'Pricing', href: '#', type: 'link' },
    { label: 'Customers', href: '#', type: 'link' },
    {
      label: 'Resources',
      type: 'mega',
      columns: [
        {
          title: 'Learn',
          items: [
            { icon: FileText, name: 'Blog', desc: 'Studio playbooks & ops', href: '#' },
            { icon: ArrowUpRight, name: 'Migration guide', desc: 'Move from any platform', href: '#' },
            { icon: Shield, name: 'REACH compliance hub', desc: 'EU ink regulations', href: '#' },
            { icon: Sparkles, name: 'Studio operations 101', desc: 'New owner essentials', href: '#' },
          ],
        },
        {
          title: 'Support',
          items: [
            { icon: MessageSquare, name: 'Help center', desc: 'Docs & how-tos', href: '#' },
            { icon: Database, name: 'API documentation', desc: 'For developers', href: '#' },
            { icon: CheckCircle2, name: 'Status', desc: 'System health', href: '#' },
            { icon: Bell, name: 'Contact support', desc: '24/7 chat & email', href: '#' },
          ],
        },
        {
          title: 'Company',
          items: [
            { icon: Heart, name: 'About InkOS', desc: 'Our story', href: '#' },
            { icon: TrendingUp, name: 'Roadmap', desc: "What we're building", href: '#' },
            { icon: Users, name: 'Careers', desc: 'Join the team', href: '#' },
            { icon: ImageIcon, name: 'Press kit', desc: 'Brand & assets', href: '#' },
          ],
        },
      ],
      footer: {
        title: 'New here? Start with the playbook',
        desc: 'A 12-page guide to running a modern tattoo studio â written by studio owners, free.',
        ctaLabel: 'Download the playbook',
        ctaHref: '#',
      },
    },
    { label: 'Changelog', href: '#', type: 'link', dot: true },
  ];

  return (
    <>
      <motion.nav
        initial={{ y: -40, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
        style={{
          position: 'fixed', top: scrolled ? 12 : 0, left: 0, right: 0, zIndex: 50,
          transition: 'all 0.4s cubic-bezier(0.22, 1, 0.36, 1)',
        }}
        onMouseLeave={handleLeave}
      >
        <div
          style={{
            maxWidth: scrolled ? 1180 : '100%',
            margin: '0 auto',
            padding: scrolled ? '10px 20px' : '20px 32px',
            background: scrolled || activeMenu ? 'rgba(247,247,245,0.85)' : 'transparent',
            backdropFilter: scrolled || activeMenu ? 'blur(20px) saturate(180%)' : 'none',
            WebkitBackdropFilter: scrolled || activeMenu ? 'blur(20px) saturate(180%)' : 'none',
            borderRadius: scrolled ? 100 : 0,
            border: scrolled ? `1px solid ${BRAND.border}` : 'none',
            display: 'flex', alignItems: 'center', justifyContent: 'space-between',
            transition: 'all 0.4s cubic-bezier(0.22, 1, 0.36, 1)',
          }}
        >
          {/* LOGO */}
          <a href="#" style={{ display: 'flex', alignItems: 'center', gap: 10, textDecoration: 'none' }}>
            <div style={{
              width: 32, height: 32, background: BRAND.onyx, color: BRAND.bone,
              borderRadius: 8, display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontFamily: "'Instrument Serif', serif", fontSize: 22, fontStyle: 'italic', lineHeight: 1,
            }}>i</div>
            <span style={{ fontFamily: 'Inter', fontWeight: 800, fontSize: 18, color: BRAND.onyx, letterSpacing: '-0.02em' }}>
              InkOS
            </span>
          </a>

          {/* DESKTOP NAV LINKS */}
          <div className="inkos-nav-desktop" style={{ display: 'flex', alignItems: 'center', gap: 4, position: 'relative' }}>
            {navItems.map(item => (
              <div
                key={item.label}
                onMouseEnter={() => item.type === 'mega' ? handleEnter(item.label) : handleLeave()}
                style={{ position: 'relative' }}
              >
                {item.type === 'link' ? (
                  <a href={item.href} style={{
                    display: 'inline-flex', alignItems: 'center', gap: 6,
                    fontFamily: 'Inter', fontSize: 14, fontWeight: 500,
                    color: BRAND.stoneDark, textDecoration: 'none',
                    padding: '8px 14px', borderRadius: 8,
                    transition: 'color 0.2s, background 0.2s',
                  }}
                  onMouseEnter={(e) => { e.currentTarget.style.color = BRAND.onyx; }}
                  onMouseLeave={(e) => { e.currentTarget.style.color = BRAND.stoneDark; }}
                  >
                    {item.label}
                    {item.dot && (
                      <span style={{
                        width: 6, height: 6, borderRadius: 100,
                        background: BRAND.rust,
                        boxShadow: `0 0 8px ${BRAND.rust}`,
                        animation: 'inkos-pulse 2s ease-in-out infinite',
                      }} />
                    )}
                  </a>
                ) : (
                  <button style={{
                    display: 'inline-flex', alignItems: 'center', gap: 4,
                    fontFamily: 'Inter', fontSize: 14, fontWeight: 500,
                    color: activeMenu === item.label ? BRAND.onyx : BRAND.stoneDark,
                    background: 'transparent', border: 'none',
                    padding: '8px 14px', borderRadius: 8,
                    cursor: 'pointer', transition: 'color 0.2s',
                  }}>
                    {item.label}
                    <ChevronDown size={14} style={{
                      transition: 'transform 0.2s',
                      transform: activeMenu === item.label ? 'rotate(180deg)' : 'rotate(0)',
                    }} />
                  </button>
                )}
              </div>
            ))}
          </div>

          {/* RIGHT: SIGN IN + CTA */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <a href="#" className="inkos-nav-signin" style={{
              fontFamily: 'Inter', fontSize: 14, fontWeight: 500, color: BRAND.onyx,
              textDecoration: 'none', padding: '8px 14px',
            }}>Sign in</a>
            <a href="#" style={{
              display: 'inline-flex', alignItems: 'center', gap: 6,
              background: BRAND.onyx, color: BRAND.bone,
              fontFamily: 'Inter', fontSize: 13, fontWeight: 600,
              padding: '10px 18px', borderRadius: 100, textDecoration: 'none',
              transition: 'transform 0.2s, background 0.2s',
            }}
            onMouseEnter={(e) => { e.currentTarget.style.transform = 'scale(1.02)'; }}
            onMouseLeave={(e) => { e.currentTarget.style.transform = 'scale(1)'; }}
            >
              Start free <ArrowRight size={14} />
            </a>
            <button
              onClick={() => setOpen(!open)}
              className="inkos-nav-burger"
              style={{
                background: 'transparent', border: 'none', color: BRAND.onyx,
                cursor: 'pointer', padding: 8, display: 'none',
              }}
              aria-label="Menu"
            >
              {open ? <X size={20} /> : <Menu size={20} />}
            </button>
          </div>
        </div>

        {/* ============ MEGA MENU PANEL (DESKTOP) ============ */}
        <AnimatePresence>
          {activeMenu && (() => {
            const active = navItems.find(i => i.label === activeMenu);
            if (!active || active.type !== 'mega') return null;
            const cols = active.columns.length;
            return (
              <motion.div
                key={activeMenu}
                initial={{ opacity: 0, y: -8 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -8 }}
                transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }}
                onMouseEnter={() => handleEnter(activeMenu)}
                onMouseLeave={handleLeave}
                style={{
                  position: 'absolute',
                  top: scrolled ? 60 : 76,
                  left: '50%',
                  transform: 'translateX(-50%)',
                  width: 'min(1100px, calc(100vw - 32px))',
                  background: BRAND.bone,
                  border: `1px solid ${BRAND.border}`,
                  borderRadius: 20,
                  boxShadow: '0 24px 60px -20px rgba(0,0,0,0.18), 0 0 0 1px rgba(0,0,0,0.02)',
                  overflow: 'hidden',
                }}
              >
                {/* Columns */}
                <div style={{
                  display: 'grid',
                  gridTemplateColumns: `repeat(${cols}, 1fr)`,
                  padding: 28,
                  gap: 24,
                }}>
                  {active.columns.map((col) => (
                    <div key={col.title}>
                      <div style={{
                        fontFamily: 'Inter', fontSize: 11, fontWeight: 700,
                        letterSpacing: '0.14em', textTransform: 'uppercase',
                        color: BRAND.stoneLight, marginBottom: 14, paddingLeft: 10,
                      }}>{col.title}</div>
                      <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                        {col.items.map(item => {
                          const Icon = item.icon;
                          return (
                            <a key={item.name} href={item.href} style={{
                              display: 'flex', alignItems: 'flex-start', gap: 12,
                              padding: '10px 10px', borderRadius: 10,
                              textDecoration: 'none',
                              transition: 'background 0.15s',
                            }}
                            onMouseEnter={(e) => e.currentTarget.style.background = BRAND.boneDeep}
                            onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
                            >
                              <div style={{
                                width: 32, height: 32, flexShrink: 0,
                                background: BRAND.boneDeep,
                                border: `1px solid ${BRAND.border}`,
                                borderRadius: 8,
                                display: 'flex', alignItems: 'center', justifyContent: 'center',
                                color: BRAND.onyx, marginTop: 1,
                              }}>
                                {Icon && <Icon size={15} strokeWidth={1.6} />}
                              </div>
                              <div style={{ minWidth: 0, flex: 1 }}>
                                <div style={{
                                  fontFamily: 'Inter', fontSize: 13.5, fontWeight: 600,
                                  color: BRAND.onyx, lineHeight: 1.3, marginBottom: 2,
                                }}>{item.name}</div>
                                <div style={{
                                  fontFamily: 'Inter', fontSize: 12, fontWeight: 400,
                                  color: BRAND.stone, lineHeight: 1.4,
                                }}>{item.desc}</div>
                              </div>
                            </a>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>

                {/* Footer band */}
                {active.footer && (
                  <a href={active.footer.ctaHref} style={{
                    display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                    background: BRAND.boneDeep,
                    borderTop: `1px solid ${BRAND.border}`,
                    padding: '18px 28px',
                    textDecoration: 'none',
                    transition: 'background 0.2s',
                  }}
                  onMouseEnter={(e) => e.currentTarget.style.background = BRAND.borderSoft}
                  onMouseLeave={(e) => e.currentTarget.style.background = BRAND.boneDeep}
                  >
                    <div>
                      <div style={{
                        fontFamily: "'Instrument Serif', serif", fontStyle: 'italic',
                        fontSize: 18, color: BRAND.onyx, marginBottom: 2,
                      }}>{active.footer.title}</div>
                      <div style={{
                        fontFamily: 'Inter', fontSize: 12.5, color: BRAND.stoneDark,
                      }}>{active.footer.desc}</div>
                    </div>
                    <div style={{
                      display: 'inline-flex', alignItems: 'center', gap: 6,
                      fontFamily: 'Inter', fontSize: 13, fontWeight: 600,
                      color: BRAND.onyx, whiteSpace: 'nowrap', paddingLeft: 24,
                    }}>
                      {active.footer.ctaLabel} <ArrowRight size={14} />
                    </div>
                  </a>
                )}
              </motion.div>
            );
          })()}
        </AnimatePresence>
      </motion.nav>

      {/* ============ MOBILE MENU (ACCORDION) ============ */}
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="inkos-nav-mobile"
            style={{
              position: 'fixed', top: 76, left: 16, right: 16, zIndex: 49,
              background: BRAND.bone, borderRadius: 16, padding: 8,
              border: `1px solid ${BRAND.border}`,
              maxHeight: 'calc(100vh - 96px)', overflowY: 'auto',
              boxShadow: '0 24px 60px -20px rgba(0,0,0,0.18)',
              display: 'none',
            }}
          >
            {navItems.map(item => {
              if (item.type === 'link') {
                return (
                  <a key={item.label} href={item.href} onClick={() => setOpen(false)} style={{
                    display: 'flex', alignItems: 'center', gap: 8,
                    padding: '14px 16px', fontFamily: 'Inter', fontSize: 15,
                    fontWeight: 500, color: BRAND.onyx, textDecoration: 'none',
                    borderRadius: 10,
                  }}>
                    {item.label}
                    {item.dot && (
                      <span style={{
                        width: 6, height: 6, borderRadius: 100, background: BRAND.rust,
                      }} />
                    )}
                  </a>
                );
              }
              const isExpanded = mobileExpanded === item.label;
              return (
                <div key={item.label}>
                  <button
                    onClick={() => setMobileExpanded(isExpanded ? null : item.label)}
                    style={{
                      width: '100%', display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                      padding: '14px 16px', background: 'transparent', border: 'none',
                      fontFamily: 'Inter', fontSize: 15, fontWeight: 500, color: BRAND.onyx,
                      cursor: 'pointer', borderRadius: 10, textAlign: 'left',
                    }}
                  >
                    {item.label}
                    <ChevronDown size={16} style={{
                      transition: 'transform 0.2s',
                      transform: isExpanded ? 'rotate(180deg)' : 'rotate(0)',
                    }} />
                  </button>
                  <AnimatePresence>
                    {isExpanded && (
                      <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: 'auto', opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        transition={{ duration: 0.22 }}
                        style={{ overflow: 'hidden' }}
                      >
                        <div style={{ padding: '4px 8px 12px' }}>
                          {item.columns.map(col => (
                            <div key={col.title} style={{ marginBottom: 8 }}>
                              <div style={{
                                fontFamily: 'Inter', fontSize: 10, fontWeight: 700,
                                letterSpacing: '0.14em', textTransform: 'uppercase',
                                color: BRAND.stoneLight, padding: '8px 8px 6px',
                              }}>{col.title}</div>
                              {col.items.map(sub => {
                                const Icon = sub.icon;
                                return (
                                  <a key={sub.name} href={sub.href} onClick={() => setOpen(false)} style={{
                                    display: 'flex', alignItems: 'center', gap: 10,
                                    padding: '10px 8px', borderRadius: 8,
                                    textDecoration: 'none', color: BRAND.onyx,
                                  }}>
                                    {Icon && (
                                      <div style={{
                                        width: 28, height: 28, flexShrink: 0,
                                        background: BRAND.boneDeep,
                                        border: `1px solid ${BRAND.border}`,
                                        borderRadius: 7,
                                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                                        color: BRAND.onyx,
                                      }}>
                                        <Icon size={13} strokeWidth={1.6} />
                                      </div>
                                    )}
                                    <div>
                                      <div style={{
                                        fontFamily: 'Inter', fontSize: 13.5, fontWeight: 600,
                                        color: BRAND.onyx, lineHeight: 1.2,
                                      }}>{sub.name}</div>
                                      <div style={{
                                        fontFamily: 'Inter', fontSize: 11.5,
                                        color: BRAND.stone, lineHeight: 1.3,
                                      }}>{sub.desc}</div>
                                    </div>
                                  </a>
                                );
                              })}
                            </div>
                          ))}
                        </div>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
              );
            })}

            {/* Mobile footer CTAs */}
            <div style={{
              borderTop: `1px solid ${BRAND.borderSoft}`, marginTop: 8,
              padding: 12, display: 'flex', gap: 8,
            }}>
              <a href="#" onClick={() => setOpen(false)} style={{
                flex: 1, textAlign: 'center', padding: '12px 14px',
                fontFamily: 'Inter', fontSize: 14, fontWeight: 600,
                color: BRAND.onyx, background: BRAND.boneDeep,
                borderRadius: 100, textDecoration: 'none',
              }}>Sign in</a>
              <a href="#" onClick={() => setOpen(false)} style={{
                flex: 1, padding: '12px 14px',
                fontFamily: 'Inter', fontSize: 14, fontWeight: 600,
                color: BRAND.bone, background: BRAND.onyx,
                borderRadius: 100, textDecoration: 'none',
                display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
              }}>Start free <ArrowRight size={14} /></a>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

